+ OR NOT clearledger.canonical(d->>'debitParty',2,64) OR NOT clearledger.canonical(d->>'creditParty',2,64)
+ OR d->>'debitParty'=d->>'creditParty' OR NOT clearledger.canonical(d->>'clearingStage',2,64)
